    // the coaster: rails, spine and support columns along the real track, estimated height profile
    const T = D.track, S = [0]; for (let i = 1; i < T.length; i++) S.push(S[i - 1] + Math.hypot(T[i][0] - T[i - 1][0], T[i][1] - T[i - 1][1]));
