    const VER = '#b33a2b', ROOF = '#53585d', RID = '#3a3e42', UND = '#8e3326', WALL = '#ece5d5', ST = '#a39d92', GOLD = {c:'#caa23e', glow:'#ffd27a', gk:0.25}, CU = '#5f8b78', DARK = '#2b2622';
    for (const P of D.lotus) ctx.paint(P, [96, 132, 104]);
