      tRoof(B, f, {L:L + 1.6, W:W + 1.6, y:y0 + wallH + 0.3, h:roofH, k:Math.max(0.5, (L - W)/2 + 1.5), gab, pw:1.6, lift:0.5, col:cols.roof || ROOF, hip:RID, und:UND, gcol:cols.wall, rw:0.5, nt:6});
